<?php
declare(strict_types=1);$active_module='ical';require_once __DIR__.'/layout.php';require_once __DIR__.'/../config/ical.php';if(empty($_SESSION['supplier_csrf']))$_SESSION['supplier_csrf']=bin2hex(random_bytes(32));$u=$supplier_user;$pdo=db();$message='';$error='';try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['supplier_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması geçersiz.');$action=$_POST['action']??'';if($action==='create'){$property=(int)$_POST['property_id'];$direction=$_POST['direction']==='import'?'import':'export';$label=trim((string)$_POST['label']);$url=trim((string)$_POST['source_url']);if(!$property||$label==='')throw new RuntimeException('Ürün ve bağlantı adı zorunludur.');if($direction==='import'&&(!filter_var($url,FILTER_VALIDATE_URL)||!preg_match('/\.ics(?:$|[?#])/i',$url)))throw new RuntimeException('İçe aktarma için .ics ile biten geçerli takvim URL’si gerekir.');$check=$pdo->prepare("SELECT id FROM properties WHERE id=? AND supplier_id=? AND property_type IN ('villa','yacht')");$check->execute([$property,$u['supplier_id']]);if(!$check->fetch())throw new RuntimeException('iCal yalnızca size ait tatil evi veya yat ürünlerine eklenebilir.');$pdo->prepare('INSERT INTO ical_connections(supplier_id,property_id,direction,label,access_token,source_url) VALUES(?,?,?,?,?,?)')->execute([$u['supplier_id'],$property,$direction,$label,bin2hex(random_bytes(32)),$direction==='import'?$url:null]);$message='iCal bağlantısı oluşturuldu.';}if($action==='refresh'){$result=ical_import_connection((int)$_POST['connection_id'],(int)$u['supplier_id']);if(!$result['ok'])throw new RuntimeException($result['message']);$message=$result['message'];}if($action==='pause'){$pdo->prepare("UPDATE ical_connections SET status='paused' WHERE id=? AND supplier_id=?")->execute([(int)$_POST['connection_id'],$u['supplier_id']]);$message='Bağlantı duraklatıldı.';}}}catch(Throwable $e){$error=$e->getMessage();}$q=$pdo->prepare("SELECT id,name,property_type FROM properties WHERE supplier_id=? AND property_type IN ('villa','yacht') ORDER BY name");$q->execute([$u['supplier_id']]);$products=$q->fetchAll();$q=$pdo->prepare('SELECT c.*,p.name property_name,(SELECT COUNT(*) FROM ical_events e WHERE e.ical_connection_id=c.id) event_count FROM ical_connections c JOIN properties p ON p.id=c.property_id WHERE c.supplier_id=? ORDER BY c.id DESC');$q->execute([$u['supplier_id']]);$connections=$q->fetchAll();supply_start('iCal takvim bağlantıları',$active_module);?><section class="page-intro"><p>Tatil evi ve yat ürünleriniz için sınırsız iCal bağlantısı ekleyin. Airbnb, Vrbo, Booking.com ve diğer .ics sağlayıcılarından blokları içe alın; NEXUS takviminizi de her kanal için ayrı URL ile dışa verin.</p></section><?php if($message):?><p class="save-success">✓ <?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><section class="next-module"><h2>Yeni iCal bağlantısı</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="create"><div class="form-row"><label>Tatil evi / yat<select name="property_id"><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'].' · '.$p['property_type'])?></option><?php endforeach;?></select></label><label>Bağlantı yönü<select name="direction"><option value="import">Dış takvimi içe aktar</option><option value="export">NEXUS takvimini dışa aktar</option></select></label><label>Bağlantı adı<input name="label" placeholder="Airbnb Ana Takvim" required></label></div><label>Kaynak iCal URL’si <small>(yalnızca içe aktarmada; .ics ile bitmeli)</small><input name="source_url" type="url" placeholder="https://.../calendar.ics"></label><button>iCal bağlantısını oluştur</button></form></section><section class="next-module"><h2>Bağlantılar</h2><?php foreach($connections as $c):?><article><h3><?=htmlspecialchars($c['property_name'])?> · <?=htmlspecialchars($c['label'])?></h3><p><b><?=htmlspecialchars($c['direction'])?></b> · <?=htmlspecialchars($c['status'])?> · <?= (int)$c['event_count']?> blok · son senkronizasyon <?=htmlspecialchars($c['last_sync_at']??'henüz yok')?></p><?php if($c['direction']==='export'):?><label>NEXUS iCal URL’si<input readonly value="https://nexustraveltech.com/api/ical?token=<?=htmlspecialchars($c['access_token'])?>"></label><p>Bu adresi Airbnb/Vrbo/Booking.com kanalındaki “calendar import” alanına yapıştırın.</p><?php else:?><p>Kaynak: <?=htmlspecialchars($c['source_url'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="refresh"><input type="hidden" name="connection_id" value="<?=$c['id']?>"><button>Şimdi içe aktar</button></form><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="pause"><input type="hidden" name="connection_id" value="<?=$c['id']?>"><button>Bağlantıyı duraklat</button></form><?= $c['last_error']?'<p class="login-error">'.htmlspecialchars($c['last_error']).'</p>':''?></article><?php endforeach;?></section><?php supply_end();
